/**
 * Applies all patches to router.*.js code and returns the modified code.
 *
 * Minified identifiers change at every xTool Studio build (xzt, X0, M2, ...),
 * so every target below is located with a regular expression that captures the
 * current names, instead of relying on hard-coded minified symbols.
 */
export function applyCircleMaskPatch(code) {
  if (code.includes(PLUGIN_MARKER)) {
    throw new Error('El plugin Shape Mask ya está presente (PLUGIN_MARKER encontrado).');
  }

  const BT = '`';
  const MASK_LABEL = 'Máscara'; // label of the "Mask" chip (translated)
  const failStep = (stepName, count, expected) => {
    throw new Error(`No se pudo aplicar el paso "${stepName}": ${count} coincidencias encontradas (esperadas: ${expected}).`);
  };

  /** Applies a regex step: replacer(match, ...groups, offset, whole) -> string. */
  const applyStep = (src, stepName, re, replacer, expected = 1) => {
    const flags = re.flags.includes('g') ? re.flags : re.flags + 'g';
    const rx = new RegExp(re.source, flags);
    const count = [...src.matchAll(rx)].length;
    if (count !== expected) failStep(stepName, count, expected);
    return src.replace(rx, replacer);
  };

  /** Last captured group-1 match of `re` found in the `span` characters before `index`. */
  const lookBehind = (src, index, re, span = 1500) => {
    const chunk = src.slice(Math.max(0, index - span), index);
    const all = [...chunk.matchAll(new RegExp(re.source, 'g'))];
    return all.length ? all[all.length - 1] : null;
  };

  let patched = code;

  // ───────────────────────────── MaskCtrl component ─────────────────────────────
  const mcOpen = /(\w+)=(\w+)\(\{__name:`MaskCtrl`/g;
  const mcMatches = [...patched.matchAll(mcOpen)];
  if (mcMatches.length !== 1) failStep('Locate MaskCtrl component', mcMatches.length, 1);
  const mcStart = mcMatches[0].index;
  const nextComp = /\w+=\w+\(\{__name:`/g;
  nextComp.lastIndex = mcStart + 30;
  const nx = nextComp.exec(patched);
  const mcEnd = nx ? nx.index : patched.length;
  let mc = patched.slice(mcStart, mcEnd);
  const mcRest = patched.slice(mcEnd);
  const beforeMc = patched.slice(0, mcStart);

  // Symbols used by the MaskCtrl render function (captured, not hard-coded)
  const symFrag = mc.match(/\[e\.colorRangeToolValue,e\.subjectExtractionToolValue\]\.includes\(e\.currentToolSelect\)\?\((\w+)\(\),(\w+)\((\w+),\{key:2\},\[/);
  if (!symFrag) failStep('MaskCtrl Edit section (symbols)', 0, 1);
  const [, S_openBlock, S_createBlockEl, S_Fragment] = symFrag;

  const symList = mc.match(/(\w+)\(`div`,(\w+),\[e\.currentToolSelect===e\.colorRangeToolValue\?\((\w+)\(!0\),(\w+)\((\w+),\{key:0\},(\w+)\((\w+)\((\w+)\),t=>/);
  if (!symList) failStep('MaskCtrl Retain/Remove buttons (symbols)', 0, 1);
  const S_createVNodeEl = symList[1];
  const S_renderList = symList[6];
  const S_unref = symList[7];

  const symClass = mc.match(/class:(\w+)\(\[`tool-chip`/);
  if (!symClass) failStep('MaskCtrl normalizeClass symbol', 0, 1);
  const S_normClass = symClass[1];

  const symRef = mc.match(/,(\w+)=(\w+)\(!1\),(\w+)=\2\(``\),/);
  if (!symRef) failStep('Vue ref symbol', 0, 1);
  const S_ref = symRef[2];

  // 2. Suppress empty video tooltip when hovering the "circleMask" chip
  mc = applyStep(
    mc, 'MaskCtrl tooltip guard for circleMask',
    /(\w+)=e=>\{(\w+)\(\),(\w+)\.value=e,(\w+)\.value=!0\}/,
    (m, a, clr, b, c) => `${a}=e=>{if(e===${BT}circleMask${BT})return;${clr}(),${b}.value=e,${c}.value=!0}`
  );

  // 3a. Show the Edit section (Retain / Remove) when circleMask is selected
  mc = applyStep(
    mc, 'MaskCtrl Edit section for circleMask',
    /\[e\.colorRangeToolValue,e\.subjectExtractionToolValue\]\.includes\(e\.currentToolSelect\)\?/,
    () => `[e.colorRangeToolValue,e.subjectExtractionToolValue,${BT}circleMask${BT}].includes(e.currentToolSelect)?`
  );

  // 3b. Show the Retain / Remove buttons for circleMask
  mc = applyStep(
    mc, 'MaskCtrl Retain/Remove buttons for circleMask',
    /e\.currentToolSelect===e\.colorRangeToolValue\?(?=\(\w+\(!0\),\w+\(\w+,\{key:0\},\w+\(\w+\(\w+\),t=>[\s\S]{0,400}?setColorRangeMode)/,
    () => `[e.colorRangeToolValue,${BT}circleMask${BT}].includes(e.currentToolSelect)?`
  );

  // 5. Hide the AI "Run extraction" button for circleMask
  mc = applyStep(
    mc, 'MaskCtrl hide Run Extraction button for circleMask',
    /(e\.currentToolSelect!==e\.samToolValue)(\?\(\w+\(\),\w+\(\w+\(\w+\),\{key:\d+,class:`w-full rounded-lg! h-7! mt-3 mb-3`,id:`auto-mask-run-algorithm-btn`)/,
    (m, a, b) => `${a}&&e.currentToolSelect!==${BT}circleMask${BT}${b}`
  );

  // 4. Insert the CircleMask controls right after the "contiguous" block
  const uiVNode = buildCircleMaskUiVNode();
  mc = applyStep(
    mc, 'MaskCtrl insert CircleMask controls',
    /(\w+)\(`div`,null,(\w+)\((\w+)\((\w+)\)\(`editor\.v1_0\.connected_pixels_when`\)\),1\)\]\),_:1\}\)\]\)\):(\w+)\(``,!0\)(?=\],64\)\):\5\(``,!0\)\]\)\):\5\(``,!0\)\]\))/,
    (m, el, toDisp, unref, tfn, comment) => {
      // The UI snippet was written with fixed names (V,z,R,W,T,b,p,g,y); bind them to this build's symbols.
      const ui = `((V,z,R,W,T,b,p,g,y)=>${uiVNode})(${unref},${comment},${toDisp},${S_normClass},${S_Fragment},${S_renderList},${S_createVNodeEl},${S_openBlock},${S_createBlockEl})`;
      return `${m},${ui}`;
    }
  );

  patched = beforeMc + mc + mcRest;

  // ───────────────────────────── Runtime (plugin class + state) ─────────────────────────────
  const hooksSym = (patched.match(/this\.editor\.hooks\.before\((\w+)\.MOUSE_DOWN,this\.onMouseDown\),this\.editor\.hooks\.before\(\1\.MOUSE_MOVE/) || [])[1];
  const eventsSym = (patched.match(/this\.editor\.on\((\w+)\.TOOL_CHANGED,/) || [])[1];
  if (!hooksSym) failStep('Resolve editor Hooks enum', 0, 1);
  if (!eventsSym) failStep('Resolve editor Events enum', 0, 1);

  let runtimeCode = buildCircleMaskRuntimeCode().replace(/^var /, '');
  runtimeCode = adaptRuntime(runtimeCode, { hooksSym, eventsSym, refSym: S_ref });

  patched = applyStep(
    patched, 'Inject CircleMaskPlugin runtime before MaskCtrl',
    /(\w+=\w+\(\{__name:`MaskCtrl`)/,
    (m) => `${runtimeCode},${m}`
  );

  // ───────────────────────────── Plugin registration (2 editors) ─────────────────────────────
  const optsFor = (src, idx) => {
    const start = src.lastIndexOf('plugins:[', idx);
    const o = src.slice(start, idx).match(/new \w+\(\{color:(\w+),opacity:(\w+)\}\)/);
    return o ? { color: o[1], opacity: o[2] } : null;
  };

  // 6. Smart Mask controller (has a trailing `new X({color:..})` plugin)
  patched = applyStep(
    patched, '_Bt register xCircleMaskPlugin',
    /(new \w+\(\{boxColor:`#2661F1`,showBoxStroke:!0,isFillBox:!1\}\),new \w+,new \w+\(\{color:(\w+)\}\))\]/,
    (m, head, color, off, whole) => {
      const o = optsFor(whole, off) || { color, opacity: '.4' };
      return `${head},new xCircleMaskPlugin({color:${o.color},opacity:${o.opacity}})]`;
    }
  );

  // 14. Process Layered / Spot Color controller
  patched = applyStep(
    patched, 'rVt register xCircleMaskPlugin',
    /(new \w+\(\{boxColor:`#2661F1`,showBoxStroke:!0,isFillBox:!1\}\),new \w+)\]/,
    (m, head, off, whole) => {
      const o = optsFor(whole, off);
      if (!o) failStep('rVt register xCircleMaskPlugin (color/opacity)', 0, 1);
      return `${head},new xCircleMaskPlugin({color:${o.color},opacity:${o.opacity}})]`;
    }
  );

  // 7. Forward setColorSelectionMode to the circleMask plugin (both controllers)
  patched = applyStep(
    patched, '_Bt & rVt setColorSelectionMode forward to circleMask',
    /setColorSelectionMode\(e\)\{let t=this\.getColorSelectionPlugin\(\);t&&t\.setMode\(e\)\}/,
    () => `setColorSelectionMode(e){let t=this.getColorSelectionPlugin();t&&t.setMode(e),(this.originEditor||this.editor)?.plugins.getPlugin(${BT}circleMask${BT})?.setMode(e)}`,
    2
  );

  // ───────────────────────────── Tool enums ─────────────────────────────
  // 8. Smart Mask enum (no EDGE_EXTRACTION)
  patched = applyStep(
    patched, 'X0 enum add CIRCLE_MASK',
    /(\w+=function\(e\)\{return e\.MASK_REGION=`maskRegion`,e\.SAM=`segmentAnything`,e\.COLOR_RANGE=`colorRange`,e\.SUBJECT_EXTRACTION=`subjectExtraction`,)(e\}\(\{\}\))/,
    (m, a, b) => `${a}e.CIRCLE_MASK=${BT}circleMask${BT},${b}`
  );
  // 15. Process Layered enum (with EDGE_EXTRACTION)
  patched = applyStep(
    patched, 'M2 enum add CIRCLE_MASK',
    /(\w+=function\(e\)\{return e\.MASK_REGION=`maskRegion`,e\.SAM=`segmentAnything`,e\.COLOR_RANGE=`colorRange`,e\.SUBJECT_EXTRACTION=`subjectExtraction`,e\.EDGE_EXTRACTION=`edgeExtraction`,)(e\}\(\{\}\))/,
    (m, a, b) => `${a}e.CIRCLE_MASK=${BT}circleMask${BT},${b}`
  );

  // ───────────────────────────── Tool lists ─────────────────────────────
  // 9. Smart Mask toolOptions (color_range is the last entry)
  patched = applyStep(
    patched, 'T2 toolOptions add Shape Mask',
    /(\{label:`color_range1`,value:(\w+)\.COLOR_RANGE,tips:\{images:\w+\(\w+\),title:`color_range`,contents:\[`color_range_used`\]\}\})\]/,
    (m, head, en) => `${head},{label:${BT}${MASK_LABEL}${BT},value:${en}.CIRCLE_MASK}]`
  );
  // 18. Process Layered toolOptions (edge_extraction is the last entry)
  patched = applyStep(
    patched, 'J4 toolOptions add Shape Mask',
    /(\{label:`edge_extraction1`,value:(\w+)\.EDGE_EXTRACTION,tips:\{images:\w+\(\w+\),title:`edge_extraction`,contents:\[`extracting_edges_main2`\]\}\})\]/,
    (m, head, en) => `${head},{label:${BT}${MASK_LABEL}${BT},value:${en}.CIRCLE_MASK}]`
  );

  // ───────────────────────────── Alt/Option hotkey (10 + 17) ─────────────────────────────
  patched = applyStep(
    patched, 'Alt hotkey for CIRCLE_MASK',
    /\(t\.key===`Option`\|\|t\.key===`Alt`\)&&(\w+)\.value===`smart`&&(\w+)\.value===(\w+)\.COLOR_RANGE&&/,
    (m, tab, tool, en) => `(t.key===${BT}Option${BT}||t.key===${BT}Alt${BT})&&${tab}.value===${BT}smart${BT}&&(${tool}.value===${en}.COLOR_RANGE||${tool}.value===${en}.CIRCLE_MASK)&&`,
    2
  );

  // ───────────────────────────── Smart Mask controller: setTool handlers (11, 12, 13) ─────────────────────────────
  const modeBefore = (whole, off) => {
    const mm = lookBehind(whole, off, /setColorSelectionMode\((\w+)\.value\)/, 8000);
    return mm ? mm[1] : null;
  };
  // 11 + 12. "…SAM&&(X?.setTool(`segmentAnything`),X?.setSegmentAnythingMode(v.value))" — historyChange + tab change
  patched = applyStep(
    patched, 'T2 historyChange / tabChange handle CIRCLE_MASK',
    /(?<=:)((?:\w+\.value|\w+))===(\w+)\.SAM&&\((\w+)\?\.setTool\(`segmentAnything`\),\3\?\.setSegmentAnythingMode\((\w+)\.value\)\)/,
    (m, lhs, en, cv, samv, off, whole) => {
      const mode = modeBefore(whole, off);
      if (!mode) failStep('T2 handle CIRCLE_MASK (color mode variable)', 0, 1);
      const orig = `${lhs}===${en}.SAM?(${cv}?.setTool(${BT}segmentAnything${BT}),${cv}?.setSegmentAnythingMode(${samv}.value))`;
      return `${orig}:${lhs}===${en}.CIRCLE_MASK&&(${cv}?.setTool(${BT}circleMask${BT}),${cv}?.setColorSelectionMode(${mode}.value))`;
    },
    2
  );
  // 13. handleUpdateToolSelect
  patched = applyStep(
    patched, 'T2 handleUpdateToolSelect (ae) handle CIRCLE_MASK',
    /(?<=:)(\w+\.value)===(\w+)\.SUBJECT_EXTRACTION&&\(t\.extractionResult\?(\w+)\?\.setTool\(`extractMask`\):\3\?\.setTool\(``\)\)/,
    (m, lhs, en, cv, off, whole) => {
      const mode = modeBefore(whole, off);
      if (!mode) failStep('T2 handleUpdateToolSelect (color mode variable)', 0, 1);
      const orig = `${lhs}===${en}.SUBJECT_EXTRACTION?(t.extractionResult?${cv}?.setTool(${BT}extractMask${BT}):${cv}?.setTool(${BT}${BT}))`;
      return `${orig}:${lhs}===${en}.CIRCLE_MASK&&(${cv}?.setTool(${BT}circleMask${BT}),${cv}?.setColorSelectionMode(${mode}.value))`;
    }
  );

  // ───────────────────────────── Process Layered controller: setTool handlers (16, 19) ─────────────────────────────
  patched = applyStep(
    patched, 'J4 G4() / oe() handle CIRCLE_MASK',
    /else (\w+)===(\w+)\.EDGE_EXTRACTION&&\(t\.edgeResult\?(\w+\.canvas)\?\.setTool\(`edgeExtraction`\):\3\?\.setTool\(``\)\)(?=\})/,
    (m, v, en, cv, off, whole) => {
      const mode = modeBefore(whole, off);
      if (!mode) failStep('J4 handle CIRCLE_MASK (color mode variable)', 0, 1);
      const orig = `else ${v}===${en}.EDGE_EXTRACTION?(t.edgeResult?${cv}?.setTool(${BT}edgeExtraction${BT}):${cv}?.setTool(${BT}${BT}))`;
      return `${orig}:${v}===${en}.CIRCLE_MASK&&(${cv}?.setTool(${BT}circleMask${BT}),${cv}?.setColorSelectionMode(${mode}.value))`;
    },
    2
  );

  return patched;
}

/**
 * Adapts the runtime snippet (written against the v1.9.x minified symbols) to the
 * symbols of the current build and removes its dependencies on internal helpers.
 */
function adaptRuntime(rt, { hooksSym, eventsSym, refSym }) {
  const BT = '`';
  const helpers =
    'xDP=(o,k,v)=>(Object.defineProperty(o,k,{value:v,enumerable:!0,configurable:!0,writable:!0}),o),' +
    'xIsImg=o=>!!o&&o.type===' + BT + 'image' + BT + '&&!!o.transform,' +
    'xW2L=(p,o)=>{let t=o.transform,x=p.x-t.x,y=p.y-t.y;if(t.rotation!==0){let c=Math.cos(-t.rotation),s=Math.sin(-t.rotation),a=x*c-y*s,b=x*s+y*c;x=a,y=b}return x/=t.scaleX,y/=t.scaleY,{x:x+o.width/2,y:y+o.height/2}},' +
    'xL2W=(p,o)=>{let t=o.transform,x=(p.x-o.width/2)*t.scaleX,y=(p.y-o.height/2)*t.scaleY;if(t.rotation!==0){let c=Math.cos(t.rotation),s=Math.sin(t.rotation),a=x*c-y*s,b=x*s+y*c;x=a,y=b}return{x:x+t.x,y:y+t.y}},';

  let out = rt;
  // helpers right after the marker comment
  out = out.replace(/^(\/\*[^*]*\*\/)/, (m) => m + helpers);
  out = out.replace(/(?<![\w$.])G\(this,/g, 'xDP(this,');
  out = out.replace(/(?<![\w$.])Us\./g, hooksSym + '.');
  out = out.replace(/(?<![\w$.])ec\./g, eventsSym + '.');
  out = out.replace(/(\w+) instanceof k0/g, 'xIsImg($1)');
  out = out.replace(/(?<![\w$.])Hs\(/g, 'xW2L(');
  out = out.replace(/(?<![\w$.])qs\(/g, 'xL2W(');
  out = out.replace(/,Vs\.CIRCLE_MASK=`circleMask`/g, '');
  out = out.replace(/xCircleMaskState=B\(/, 'xCircleMaskState=' + refSym + '(');
  return out;
}
